function openDoor(d){let dialog=document.createElement('dialog');dialog.innerHTML=`<h2>Door connection</h2><p class="small">${esc(room(d.a)?.name)} ↔ ${esc(room(d.b)?.name)}</p>${field('Clear width · m','width',d.width,'number')}<label class="field"><span>Position along shared wall · %</span><input id="dooroffset" type="range" min="0" max="100" value="${d.offset*100}"></label><label><input id="openjoin" type="checkbox" ${d.kind==='open'?'checked':''}> Open full-width connection (no door)</label><label><input id="sealed" type="checkbox" ${d.sealed?'checked':''}> Sealed / discoverable passage</label><p class="small">Door position follows the common wall. Width must fit with 0.1 m clear at each end.</p><button id="savedoor">Apply</button> <button id="canceld">Cancel</button>`;document.body.append(dialog);dialog.showModal();dialog.querySelector('#canceld').onclick=()=>{dialog.close();dialog.remove()};dialog.querySelector('#savedoor').onclick=()=>{const w=Number(dialog.querySelector('[data-key=width]').value),offset=Number(dialog.querySelector('#dooroffset').value)/100,sealed=dialog.querySelector('#sealed').checked;if(!Number.isFinite(w)||w<.5||w>8){notify('Door width must be 0.5–8 m');return}commit(()=>Object.assign(d,{width:w,offset,sealed,kind:dialog.querySelector('#openjoin').checked?'open':'door'}));dialog.close();dialog.remove()}}
