function download(name,data,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([data],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}$('variant').onchange=e=>switchVariant(e.target.value);$('geometryexport').onclick=()=>download('kern-'+variant+'-geometry.json',JSON.stringify(buildGeometry(model),null,2),'application/json');$('export').onclick=()=>{download('kern-plan.json',JSON.stringify(model,null,2),'application/json');notify('All levels exported as editable JSON')};$('svgexport').onclick=()=>{download(`kern-${floorId}.svg`,`<svg xmlns="http://www.w3.org/2000/svg" viewBox="${bounds(true).x} ${bounds(true).y} ${bounds(true).w} ${bounds(true).h}" width="1360" height="1040">${planMarkup(true)}</svg>`,'image/svg+xml');notify(floorId+' exported as vector SVG')};$('import').onclick=()=>$('file').click();function validateImport(p){if(p?.version!==1||p.units!=='metres'||!p.floors||!p.floors.L0||Object.keys(p.floors).length>20)throw Error('Expected a KERN version 1 plan');for(const id of Object.keys(p.floors)){const f=p.floors[id];if(!f||!Array.isArray(f.rooms)||!Array.isArray(f.doors)||!Array.isArray(f.entrances)||f.rooms.length>300||f.doors.length>600)throw Error('Missing floor data or too many objects');const ids=new Set();for(const r of f.rooms){if(typeof r.id!=='string'||ids.has(r.id)||typeof r.name!=='string'||r.name.length>150||!colors[r.type])throw Error('Invalid room data');ids.add(r.id);if(r.z!==undefined&&(!Number.isFinite(r.z)||Math.abs(r.z)>150))throw Error('Invalid room elevation');for(const k of ['x','y','w','h'])if(!Number.isFinite(r[k])||Math.abs(r[k])>150||Math.abs(r[k]*10-Math.round(r[k]*10))>1e-6)throw Error('Room dimensions must use 0.1 m increments');if(r.w<1||r.h<1)throw Error('Invalid room size')}for(const d of f.doors)if(!ids.has(d.a)||!ids.has(d.b)||!Number.isFinite(d.width)||d.width<.5||d.width>8||!Number.isFinite(d.offset)||d.offset<0||d.offset>1)throw Error('Invalid door data');if(f.entrances.some(id=>!ids.has(id)))throw Error('Invalid entrance');for(const e of(f.externals||[f.external].filter(Boolean)))if(!ids.has(e.room)||!['e','w','n','s'].includes(e.side)||!Number.isFinite(e.width))throw Error('Invalid approach')}}$('file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2e6)throw Error('File exceeds 2 MB');const p=JSON.parse(await file.text());validateImport(p);commit(()=>{model=p;selected=null;viewBounds=null});notify('All levels restored')}catch(err){alert('Could not open plan: '+err.message)}e.target.value=''};$('reset').onclick=()=>{if(confirm('Restore this layout’s original plan? You can undo this. Save JSON first to keep a separate copy.'))commit(()=>{model=clone(seedFor(variant));selected=null;viewBounds=null})};window.onkeydown=e=>{if(e.key==='Escape'&&drag){e.preventDefault();finishDrag(true);return}if(/INPUT|SELECT|TEXTAREA/.test(e.target.tagName)||document.querySelector('dialog[open]'))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo()}if(!preview&&selected&&['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)){const r=room(selected);if(!canEdit(r))return;e.preventDefault();commit(()=>{r.x+=e.key==='ArrowLeft'?-.5:e.key==='ArrowRight'?.5:0;r.y+=e.key==='ArrowUp'?-.5:e.key==='ArrowDown'?.5:0;r.x=Math.max(-150,Math.min(150,r.x));r.y=Math.max(-150,Math.min(150,r.y));syncStairEdit(r)})}};
